starterCss:
/* Graph paper: the background is drawn with two gradients. */
body { font-family: "Courier New", Courier, monospace; margin: 0; padding: 1.2rem; color: #1F3A5F;
  background-color: #F6F8FB;
  background-image: linear-gradient(#DCE4EE 1px, transparent 1px), linear-gradient(90deg, #DCE4EE 1px, transparent 1px);
  background-size: 20px 20px; }
h1 { font-size: 2rem; margin: 0 0 .3rem; text-transform: uppercase; letter-spacing: .05em; }
img { display: block; margin: .6rem 0 1rem; border: 3px solid #1F3A5F; background: #fff; }
table { border-collapse: collapse; background: #fff; border: 3px solid #1F3A5F; }
caption { font-weight: bold; text-align: left; padding: .4rem 0; }
th, td { border: 1px solid #1F3A5F; padding: .5rem .8rem; text-align: left; }
th { background: #1F3A5F; color: #fff; }
tr:nth-child(even) td { background: #EEF3FA; }
